from typing import List, Tuple

def f(N: int, M: int, edges: List[Tuple[int, int]]) -> int:
    connectedNodes = [False] * (N + 1)
    for node1, node2 in edges:
        connectedNodes[node1] = True
        connectedNodes[node2] = True
    numOfNeighbors = [0] * (N + 1)
    nodeGroups = [[] for _ in range(N + 1)]
    for node1, node2 in edges:
        numOfNeighbors[node1 - 1] += 1
        numOfNeighbors[node2 - 1] += 1
    for node in range(1, N + 1):
        if not connectedNodes[node]:
            nodeGroups[numOfNeighbors[node - 1]].append(node)
    return len(nodeGroups[nodeGroups.index(min(nodeGroups))])

print(f(6, 5, [(1, 2), (1, 3), (1, 4), (2, 5), (2, 6)]))  # Outputs: 3
